'use strict';

// MODULES //

var path = require( 'node:path' );
var boundedMessage = require( '@data-apis/errors/bounded-message' );
var ensureEmptyDirectory = require( '@data-apis/files/ensure-empty-directory' );
var writeNoClobber = require( '@data-apis/files/write-no-clobber' );
var loadRegistry = require( '@data-apis/registry/load' );
var sourceFingerprint = require( '@data-apis/registry/source-fingerprint' );
var validateReport = require( '@data-apis/report/validate' );
var createEnvelope = require( '@data-apis/record/create-envelope' );
var gzipEnvelope = require( '@data-apis/record/gzip-envelope' );
var indexRecord = require( '@data-apis/record/index-record' );
var recordRelativePath = require( '@data-apis/record/relative-path' );
var serializeIndex = require( '@data-apis/record/serialize-index' );
var validateEnvelope = require( '@data-apis/record/validate-envelope' );
var validateRepository = require( '@data-apis/repository/validate' );
var fetchCiArtifact = require( '@data-apis/sources/fetch-ci-artifact' );
var fetchUrl = require( '@data-apis/sources/fetch-url' );
var decodePayload = require( '@data-apis/payload/decode' );
var createSummary = require( '@data-apis/summary/create' );
var writeActionsSummary = require( '@data-apis/summary/write-actions' );
var sha256 = require( '@data-apis/canonical/sha256' );


// FUNCTIONS //

/**
* Compares optional member names by raw UTF-8 bytes.
*
* @private
* @param {string|undefined} left - first member
* @param {string|undefined} right - second member
* @returns {number} ordering
*/
function compareMembers( left, right ) {
	return Buffer.compare( Buffer.from( left || '', 'utf8' ), Buffer.from( right || '', 'utf8' ) );
}

/**
* Creates a source summary entry.
*
* @private
* @param {Object} library - library definition
* @param {Object} source - source definition
* @returns {Object} result
*/
function createSourceResult( library, source ) {
	return {
		'library_id': library.id,
		'source_id': source.id,
		'status': 'ok',
		'dispositions': [],
		'errors': []
	};
}

/**
* Records a rejected report candidate.
*
* @private
* @param {Object} result - source result
* @param {string|undefined} member - ZIP member
* @param {Error} error - validation error
*/
function reject( result, member, error ) {
	var message = boundedMessage( error );
	var disposition = {
		'status': 'rejected',
		'message': message
	};

	if ( member ) {
		disposition.member = member;
	}
	result.errors.push( message );
	result.dispositions.push( disposition );
}

/**
* Consolidates byte-identical reports deterministically.
*
* @private
* @param {Array} candidates - validated candidates
* @param {Object} summary - harvest summary
* @param {string} sourceKey - source key
* @returns {Array} unique candidates
*/
function deduplicateCandidates( candidates, summary, sourceKey ) {
	var hashes = new Map();

	candidates.forEach( function addCandidate( candidate ) {
		var existing = hashes.get( candidate.reportSha256 );

		if ( !existing || compareMembers( candidate.member, existing.member ) < 0 ) {
			hashes.set( candidate.reportSha256, candidate );
		}
	} );
	if ( hashes.size !== candidates.length ) {
		summary.warnings.push( sourceKey + ': duplicate ZIP members contained identical reports; the UTF-8 byte-smallest member was retained' );
	}
	return Array.from( hashes.values() );
}

/**
* Rejects unsupported bundled history within one inferred variant.
*
* @private
* @param {Array} candidates - candidates
* @param {Object} result - source result
* @returns {Array} unambiguous candidates
*/
function rejectAmbiguousVariants( candidates, result ) {
	var groups = new Map();
	var accepted = [];

	candidates.forEach( function addCandidate( candidate ) {
		if ( !groups.has( candidate.variantKey ) ) {
			groups.set( candidate.variantKey, [] );
		}
		groups.get( candidate.variantKey ).push( candidate );
	} );
	groups.forEach( function evaluate( group ) {
		var message;

		if ( group.length === 1 ) {
			accepted.push( group[ 0 ] );
			return;
		}
		message = 'Payload contains ' + group.length + ' distinct reports for inferred variant ' + group[ 0 ].variantKey;
		result.errors.push( message );
		group.forEach( function addRejection( candidate ) {
			result.dispositions.push( Object.assign( {
				'status': 'rejected',
				'series_key': candidate.seriesKey,
				'variant_key': candidate.variantKey,
				'message': message
			}, candidate.member ? { 'member': candidate.member } : {} ) );
		} );
	} );
	return accepted;
}

/**
* Resolves a source fetcher.
*
* @private
* @param {Object} source - source definition
* @param {Object} adapters - injected adapters
* @returns {Function} fetcher
*/
function sourceFetcher( source, adapters ) {
	if ( source.type === 'ci_artifact' ) {
		return adapters.ciArtifact || fetchCiArtifact;
	}
	if ( source.type === 'url' ) {
		return adapters.url || fetchUrl;
	}
	throw new Error( 'Unsupported source type: ' + source.type );
}

/**
* Compares report candidates deterministically.
*
* @private
* @param {Object} left - first candidate
* @param {Object} right - second candidate
* @returns {number} ordering
*/
function compareCandidates( left, right ) {
	if ( left.timestamp < right.timestamp ) {
		return -1;
	}
	if ( left.timestamp > right.timestamp ) {
		return 1;
	}
	if ( left.reportSha256 < right.reportSha256 ) {
		return -1;
	}
	if ( left.reportSha256 > right.reportSha256 ) {
		return 1;
	}
	return 0;
}


// MAIN //

/**
* Runs a complete harvest without mutating checked-in data.
*
* @param {Object} options - harvest options
* @param {string} options.rootDirectory - repository root
* @returns {Promise<Object>} summary, manifest, and output directory
*/
async function run( options ) {
	var parsedCandidates;
	var blockedProviders;
	var rootDirectory;
	var outputDirectory;
	var sourceResult;
	var sourceKey;
	var dataDirectory;
	var registryPath;
	var manifestFiles;
	var retrievedAt;
	var currentHashes;
	var relativePath;
	var indexRows;
	var freshnessKey;
	var otherSources;
	var disposition;
	var indexBytes;
	var candidates;
	var repository;
	var validated;
	var registry;
	var adapters;
	var envelope;
	var outputPath;
	var baseSha;
	var manifest;
	var summary;
	var fetched;
	var fetcher;
	var decoded;
	var report;
	var library;
	var source;
	var unique;
	var newest;
	var candidate;
	var item;
	var gzip;
	var now;

	rootDirectory = options.rootDirectory;
	registryPath = options.registryPath || path.join( rootDirectory, 'registry/data.json' );
	dataDirectory = options.dataDirectory || path.join( rootDirectory, 'data' );
	outputDirectory = options.outputDirectory || path.join( rootDirectory, 'build/harvest-output' );
	baseSha = options.baseSha || process.env.GITHUB_SHA || 'local';
	now = options.now === undefined ? Date.now() : options.now;
	retrievedAt = new Date( Math.floor( now / 1000 ) * 1000 ).toISOString().replace( '.000Z', 'Z' );
	registry = await loadRegistry( registryPath );
	repository = await validateRepository( {
		'dataDirectory': dataDirectory,
		'registry': registry,
		'all': false
	} );
	summary = createSummary( baseSha );
	manifestFiles = [];
	indexRows = repository.index.records.slice();
	adapters = options.adapters || {};
	blockedProviders = new Map();

	await ensureEmptyDirectory( outputDirectory );
	for ( library of registry.libraries ) {
		for ( source of library.sources ) {
			sourceResult = createSourceResult( library, source );
			sourceKey = library.id + '/' + source.id;

			summary.sources.push( sourceResult );
			try {
				if ( source.type === 'ci_artifact' && blockedProviders.has( source.provider ) ) {
					throw new Error( 'Provider ' + source.provider + ' requests suppressed after rate-limit exhaustion' + ( blockedProviders.get( source.provider ) ? ' until ' + blockedProviders.get( source.provider ) : '' ) );
				}
				fetcher = sourceFetcher( source, adapters );
				fetched = await fetcher( {
					'library': library,
					'source': source,
					'env': options.env || process.env,
					'fetchImpl': options.fetchImpl,
					'providers': options.providers,
					'expectedProjectId': repository.state.sourceProjectIds.get( sourceKey ),
					'maxRetries': options.maxRetries,
					'sleep': options.sleep
				} );
				decoded = await decodePayload( fetched.bytes, {
					'file': source.file
				} );
				parsedCandidates = [];

				for ( item of decoded.candidates ) {
					try {
						report = JSON.parse( new TextDecoder( 'utf-8', { 'fatal': true } ).decode( item.bytes ) );
						validated = validateReport( report, {
							'expectedName': library.report_name || library.id,
							'now': now
						} );

						parsedCandidates.push( Object.assign( {}, validated, item.member ? {
							'member': item.member
						} : {} ) );
					} catch ( error ) {
						reject( sourceResult, item.member, error );
					}
				}
				unique = deduplicateCandidates( parsedCandidates, summary, sourceKey );
				candidates = rejectAmbiguousVariants( unique, sourceResult ).sort( compareCandidates );

				for ( candidate of candidates ) {
					disposition = Object.assign( {
						'series_key': candidate.seriesKey,
						'variant_key': candidate.variantKey,
						'report_sha256': candidate.reportSha256,
						'timestamp': candidate.timestamp
					}, candidate.member ? { 'member': candidate.member } : {} );
					freshnessKey = sourceKey + '/' + candidate.variantKey;
					newest = repository.state.freshness.get( freshnessKey );
					currentHashes = repository.state.sourceHashes.get( sourceKey );

					if ( newest && Date.parse( candidate.timestamp ) < Date.parse( newest ) ) {
						disposition.status = 'stale';
						disposition.message = 'Report is older than newest accepted timestamp ' + newest;
						sourceResult.errors.push( disposition.message );
						sourceResult.dispositions.push( disposition );
						continue;
					}
					if ( currentHashes && currentHashes.has( candidate.reportSha256 ) ) {
						disposition.status = 'duplicate';
						sourceResult.dispositions.push( disposition );
						continue;
					}
					otherSources = repository.state.libraryHashes.get( library.id + '/' + candidate.reportSha256 );

					if ( otherSources && !otherSources.has( source.id ) ) {
						summary.warnings.push( sourceKey + ': report hash already exists under source(s) ' + Array.from( otherSources ).sort().join( ', ' ) );
					}
					envelope = createEnvelope( candidate, {
						'library': library,
						'source': source,
						'sourceFingerprint': sourceFingerprint( source ),
						'retrievedAt': retrievedAt,
						'origin': fetched.origin,
						'payloadFormat': decoded.format
					} );
					relativePath = recordRelativePath( library.id, source.id, candidate.timestamp, candidate.reportSha256 );

					validateEnvelope( envelope, relativePath, {
						'expectedName': library.report_name || library.id,
						'now': now
					} );
					gzip = gzipEnvelope( envelope );
					outputPath = 'data/' + relativePath;

					await writeNoClobber( path.join( outputDirectory, ...outputPath.split( '/' ) ), gzip );
					manifestFiles.push( {
						'path': outputPath,
						'size': gzip.length,
						'sha256': sha256( gzip )
					} );
					indexRows.push( indexRecord( envelope, relativePath, {
						'expectedName': library.report_name || library.id,
						'now': now
					} ) );
					if ( !repository.state.sourceHashes.has( sourceKey ) ) {
						repository.state.sourceHashes.set( sourceKey, new Set() );
					}
					repository.state.sourceHashes.get( sourceKey ).add( candidate.reportSha256 );
					repository.state.freshness.set( freshnessKey, candidate.timestamp );
					if ( !repository.state.libraryHashes.has( library.id + '/' + candidate.reportSha256 ) ) {
						repository.state.libraryHashes.set( library.id + '/' + candidate.reportSha256, new Set() );
					}
					repository.state.libraryHashes.get( library.id + '/' + candidate.reportSha256 ).add( source.id );
					disposition.status = 'stored';
					disposition.path = outputPath;
					sourceResult.dispositions.push( disposition );
					summary.new_records.push( outputPath );
				}
			} catch ( error ) {
				if ( source.type === 'ci_artifact' && error && error.code === 'RATE_LIMITED' ) {
					blockedProviders.set( source.provider, error.resetAt );
				}
				sourceResult.errors.push( boundedMessage( error ) );
			}
			if ( sourceResult.errors.length > 0 ) {
				sourceResult.status = 'failed';
				summary.has_source_errors = true;
			}
		}
	}
	if ( summary.new_records.length > 0 ) {
		indexBytes = Buffer.from( serializeIndex( indexRows ), 'utf8' );

		await writeNoClobber( path.join( outputDirectory, 'data/index.json' ), indexBytes );
		manifestFiles.push( {
			'path': 'data/index.json',
			'size': indexBytes.length,
			'sha256': sha256( indexBytes )
		} );
	}
	summary.new_records.sort();
	manifestFiles.sort( function compare( left, right ) {
		return left.path < right.path ? -1 : left.path > right.path ? 1 : 0;
	} );
	manifest = {
		'schema': 'harvest-manifest-v1',
		'base_sha': baseSha,
		'files': manifestFiles
	};

	await writeNoClobber( path.join( outputDirectory, 'summary.json' ), Buffer.from( JSON.stringify( summary, null, 2 ) + '\n' ) );
	await writeNoClobber( path.join( outputDirectory, 'manifest.json' ), Buffer.from( JSON.stringify( manifest, null, 2 ) + '\n' ) );
	await writeActionsSummary( summary, options.actionsSummaryPath );
	return {
		'summary': summary,
		'manifest': manifest,
		'outputDirectory': outputDirectory
	};
}


// EXPORTS //

module.exports = run;
